package httpapi

import (
	"trakt-api/internal/openapi"

	"github.com/gofiber/fiber/v2"
)

// handleOpenAPISpec serves the generated OpenAPI 3.1 document as JSON.
//
// It is generated from the live route registry, so the document always
// describes the routes this process actually serves rather than a file that
// may have gone stale. The committed openapi.yaml is the same document
// (generated by `cmd/openapi`); this endpoint exists so tooling and clients can
// fetch it from a running instance.
func handleOpenAPISpec(c *fiber.Ctx) error {
	spec, err := openapi.GenerateJSON()
	if err != nil {
		return fiber.NewError(fiber.StatusInternalServerError, "failed to generate openapi document")
	}
	c.Set(fiber.HeaderContentType, "application/json")
	return c.Send(spec)
}
